it('catches errors when error is invoked during render', () => {
	const spy = sinon.spy();
	let errored;

	function Comp() {
		useEffect(() => {
			throw new Error('hi');
		});
		return null;
	}

	class App extends Component {
		componentDidCatch(err) {
			spy();
			errored = err;
			this.forceUpdate();
		}

		render(props, state) {
			if (errored) {
				return <p>Error</p>;
			}

			return <Comp />;
		}
	}

	render(<App />, scratch);
	act(() => {
		render(<App />, scratch);
	});
	expect(spy).to.be.calledOnce;
	expect(errored)
		.to.be.an('Error')
		.with.property('message', 'hi');
	expect(scratch.innerHTML).to.equal('<p>Error</p>');
});

